import{_ as a,C as n,o,c as i,E as r,a2 as d}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.8","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.8","outline":"deep","citation":{"work":"TMPA Implementation Case","identifier":"TMPA-CASE-I0.8","language":"en","metadata":"/releases/tmpa/v1.0-rc1/metadata/implementation-case.en.cff"}},"headers":[],"relativePath":"en/publications/implementation-case-i0.8/part-01.md","filePath":"en/publications/implementation-case-i0.8/part-01.md","lastUpdated":1786355271000}'),s={name:"en/publications/implementation-case-i0.8/part-01.md"};function c(l,e,p,u,h,m){const t=n("ArticleCover");return o(),i("div",null,[r(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"An exact-input TMPA Core S0.6 product run and self-contained public reproducer for CodeFlowMu V1.6.0.",version:"I0.8",status:"S0.6 product evidence draft · 14/14 PASS",languageHref:"/zh/publications/implementation-case-i0.8",languageLabel:"简体中文"}),e[0]||(e[0]=d(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="tmpa-core-s0-6-fcop-codeflowmu-v1-6-0-and-retained-field-evidence" tabindex="-1">TMPA Core S0.6, FCoP, CodeFlowMu V1.6.0, and retained field evidence <a class="header-anchor" href="#tmpa-core-s0-6-fcop-codeflowmu-v1-6-0-and-retained-field-evidence" aria-label="Permalink to &quot;TMPA Core S0.6, FCoP, CodeFlowMu V1.6.0, and retained field evidence&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> Draft I0.8<br><strong>Status:</strong> Author-produced implementation and case report<br><strong>Normative Target:</strong> <a href="/joinwell52/en/publications/tmpa-core-specification-s0.6">TMPA Core Specification S0.6</a>, commit <code>8989657e8fde6d2e55d7606ae0adacac14fec760</code><br><strong>Product Under Test:</strong> CodeFlowMu V1.6.0, implementation commit <code>62440a526a99d2fe55019d8bb95ad2425569fcb4</code><br><strong>Evidence Capture:</strong> 2026-08-10, Asia/Shanghai<br><strong>Formal Evidence Package:</strong> <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip</code><br><strong>Archive SHA-256:</strong> <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code><br><strong>Authority Boundary:</strong> This report is evidentiary and non-normative. Only the Core Specification defines TMPA requirements.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>I0.8 evaluates CodeFlowMu V1.6.0 against all fourteen mandatory criteria in TMPA Core S0.6 using the exact raw-LF bytes fixed by the normative repository commit. The product-level result is <strong>14 PASS, 0 PARTIAL, 0 NOT RUN, and 0 FAIL</strong>. CodeFlowMu&#39;s product runner calls its own synchronous <code>GovernanceReader</code> and does not invoke the TMPA Reference Reader. The input bundle digest is <code>sha256:251914ee55922d20c9bd23943a4ff445bccaa5835e1fcc11b8562f3f384243fa</code>.</p><p>The engineering upgrade closes the observable S0.6 delta over the I0.7/S0.5 baseline: byte-identical observations retain every contributing source ID; high-risk approval requires a permitted decision-object type, a valid role assignment, an allowed role, an approval decision, and an independent actor when required; and every canonical sort uses locale-independent Unicode code-point order, including a regression over U+E000 and U+10000. CodeFlowMu&#39;s internal TMPA suite passes 23/23 tests, Runtime records 1,485 passed / 0 failed / 1 skipped, Shell records 777/777, and the locked FCoP reference implementation records 1,210 passed / 2 skipped.</p><p>The evidence archive includes a self-contained public reproducer. A clean <code>npm ci</code> and <code>npm test</code> run verifies the seven official S0.6 byte digests and executes the bundled CodeFlowMu product Reader with 14/14 PASS; no private CodeFlowMu checkout is required for this conformance slice. The strongest supportable claim remains <strong>author-run demonstrated behavior under a fixed bundle</strong>. The result is not independent certification, independent adoption, a proof for arbitrary inputs, or proof that AI hallucinations have been eliminated.</p><h1 id="_1-scope-and-research-questions" tabindex="-1">1. Scope and Research Questions <a class="header-anchor" href="#_1-scope-and-research-questions" aria-label="Permalink to &quot;1. Scope and Research Questions&quot;">​</a></h1><p>I0.8 asks:</p><ol><li>Does the CodeFlowMu V1.6.0 product Reader satisfy S0.6 C01–C14 against one exact, fixed input bundle?</li><li>Are the three observable S0.6 changes—source provenance retention, complete human-approval authorization, and locale-independent ordering—implemented without regressing the S0.5 behavior demonstrated by I0.7?</li><li>Can the conformance slice be rerun without access to the private CodeFlowMu mother repository?</li><li>Which evidence remains author-local, and which conclusions remain unsupported?</li></ol><p>The unit of judgment is a criterion-bound claim over a fixed bundle. The four evidence levels remain separate:</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning in I0.8</th><th style="text-align:right;">Reached?</th></tr></thead><tbody><tr><td>Specified</td><td>Defined normatively by TMPA Core S0.6</td><td style="text-align:right;">Yes</td></tr><tr><td>Implemented</td><td>A corresponding CodeFlowMu mechanism exists</td><td style="text-align:right;">Yes</td></tr><tr><td>Demonstrated</td><td>An execution produced inspectable evidence</td><td style="text-align:right;">Yes, for the fixed C01–C14 bundle</td></tr><tr><td>Independently Adopted</td><td>A separate organization adopted and validated the mechanism</td><td style="text-align:right;">No</td></tr></tbody></table><h1 id="_2-architecture-and-evidence-boundaries" tabindex="-1">2. Architecture and Evidence Boundaries <a class="header-anchor" href="#_2-architecture-and-evidence-boundaries" aria-label="Permalink to &quot;2. Architecture and Evidence Boundaries&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper</span></span>
<span class="line"><span>        ↓ theory guides engineering direction</span></span>
<span class="line"><span>TMPA Core S0.6</span></span>
<span class="line"><span>        ↓ fixes normative object, Reader, and conformance contract</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>        ↓ supplies the collaboration and evidence protocol</span></span>
<span class="line"><span>CodeFlowMu V1.6.0 execution and consumption layer</span></span>
<span class="line"><span>        ↓ product Reader, Runtime, roles, recovery, and audit</span></span>
<span class="line"><span>WP-13 and other bounded cases</span></span></code></pre></div><p>TMPA theory guides the engineering direction of CodeFlowMu, while Core S0.6 fixes the normative behavior evaluated in this report. FCoP is the reusable collaboration and evidence protocol used by CodeFlowMu, not an application; <code>fcop</code> and <code>fcop-mcp</code> are reference implementations rather than the protocol itself. Consistent with CodeFlowMu&#39;s engineering architecture [7], CodeFlowMu is the application execution and consumption layer: it produces coordination facts, runs the Adapter and Reader, projects the governance graph, and lets recovery and governance gates consume the reconstructed result. WP-13 remains a bounded evidence-admission case. XiaoDian AI is retained as author-reported engineering lineage only and is excluded from the evaluated evidence; neither substitutes for the S0.6 product run.</p><p>Conceptual dependency and historical formation remain distinct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CURRENT GUIDANCE: TMPA theory → Core requirements → FCoP protocol</span></span>
<span class="line"><span>                                                  → CodeFlowMu engineering</span></span>
<span class="line"><span>HISTORICAL FEEDBACK: XiaoDian practice → early TMPA → FCoP extraction</span></span>
<span class="line"><span>                                           → CodeFlowMu implementation</span></span>
<span class="line"><span>FCoP + CodeFlowMu results → current TMPA formalization</span></span></code></pre></div><p>Historical feedback explains how the theory matured; it does not invert the current authority relation. Product behavior may provide evidence or motivate a later revision, but it cannot redefine the current Core.</p><h1 id="_3-fixed-sources-and-evidence-design" tabindex="-1">3. Fixed Sources and Evidence Design <a class="header-anchor" href="#_3-fixed-sources-and-evidence-design" aria-label="Permalink to &quot;3. Fixed Sources and Evidence Design&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Source</th><th>Fixed identity</th><th>Role in I0.8</th><th>Boundary</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S0.6, commit <code>8989657…</code></td><td>Normative C01–C14 target</td><td>Specification, not product evidence</td></tr><tr><td>CodeFlowMu</td><td>V1.6.0, commit <code>62440a5…</code></td><td>Product implementation under test</td><td>Local implementation commit; not represented as a public release</td></tr><tr><td>Public reproducer</td><td>29 locked files</td><td>Public rerun of the conformance slice</td><td>Does not expose or reproduce the entire private product</td></tr><tr><td>FCoP reference implementation</td><td>commit <code>da79dfe…</code></td><td>Locked dependency baseline</td><td>Test result is not proof of the abstract protocol</td></tr><tr><td>I0.7</td><td>S0.5 / CodeFlowMu V1.4.1</td><td>Historical regression baseline</td><td>Retained with its exact earlier meaning</td></tr><tr><td>WP-13 V3</td><td>Previously published package</td><td>Evidence-gating field case</td><td>Not rerun and not promoted to a conformance proof</td></tr></tbody></table><p>The seven official S0.6 inputs—four schemas, canonicalization profile, lifecycle profile, and fixtures—are byte-identical to GitHub. The first submitted archive had Windows checkout-converted CRLF copies; publication preflight rejected it. The final archive uses raw Git blob bytes, reruns the product criteria, and regenerates every dependent digest instead of editing prior result JSON.</p>`,21))])}const g=a(s,[["render",c]]);export{b as __pageData,g as default};
